from pathlib import Path
import json
J=Path(__file__).resolve().parents[1];data=json.loads((J/'design/study.json').read_text());d3=(J/'assets/d3.v7.min.js').read_text()
html='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fruchter — Expand / Overlap / Carve</title><style>
*{box-sizing:border-box}body{margin:0;background:#fff;color:#242e31;font:15px/1.6 system-ui,sans-serif}header{padding:24px 4vw 16px;border-bottom:1px solid #ccd3cf}h1{font-size:clamp(24px,4vw,44px);line-height:1.15;margin:4px 0 12px;font-weight:500}header p{margin:0;max-width:950px;color:#647174}main{display:grid;grid-template-columns:minmax(0,1fr) 310px;gap:28px;padding:24px 4vw}svg{width:100%;height:auto;max-height:78vh;border:1px solid #e0e4e1;background:white}aside{padding:12px 0}button,select{font:inherit;padding:10px;border:1px solid #adb6b2;background:white;color:inherit;border-radius:3px}select{width:100%;margin:8px 0 20px}label{display:block;margin:10px 0}input{accent-color:#bc6b3f;margin-right:8px}button{cursor:pointer;margin-top:15px}button:hover{background:#f4e8da}#metrics{background:#f4f5f2;padding:12px;font-size:14px}#description{min-height:100px}small{display:block;color:#647174;margin-top:14px}a{color:#477ca0} @media(max-width:760px){main{grid-template-columns:1fr}svg{max-height:65vh}aside{padding:0}header{padding-top:18px}}
</style><header><small>FRUCHTER HOUSE / SPATIAL RECONSTRUCTION</small><h1>Expand / Overlap / Carve</h1><p>방향과 거리를 바꾸고, 그 결과 생긴 틈을 비웁니다. 각 상태의 실내 연결성과 중정 경계를 비교하세요. 모든 도형은 같은 좌표·상대 축척입니다.</p></header><main><div><svg id="plan" viewBox="-60 -30 1000 900" role="img" aria-label="프루흐터 하우스 중정 재구성 비교 평면"></svg></div><aside><label for="state">비교할 상태</label><select id="state"><option value="original">01 원형: A·B·C / D·E</option><option value="expanded">02 벌림: 공동 중정</option><option value="overlap">03 안으로 모아 중첩 추출</option><option value="full">04 중첩 전부 비움: 연결 실패</option><option value="selected" selected>05 선택적 비움: 선정안</option></select><label><input type="checkbox" id="ghost">원래 공간군 외곽</label><label><input type="checkbox" id="programme" checked>선정안 프로그램</label><label><input type="checkbox" id="flows" checked>선정안 동선</label><label><input type="checkbox" id="details" checked>선정안 벽·가구</label><p id="description" aria-live="polite"></p><div id="metrics"></div><button id="download">현재 평면 SVG 저장</button><small>회전 A −14° / B +18° / C +10°. 벌림과 중첩안의 이동량은 서로 다릅니다. U는 원본 A 안쪽 변 길이이며 실측 미터가 아닙니다. 성능·법규·구조 검증 전 설계 가설입니다.</small></aside></main><script>__D3__</script><script>
const S=__DATA__,A=S.alternatives.A,B=S.alternatives.B,svg=d3.select('#plan');
const path=g=>[g.outer,...(g.holes||[])].map(p=>'M'+p.map(q=>q.join(',')).join('L')+'Z').join('');
function polys(gs,fill,stroke='#242e31',width=2,dash=null){return svg.append('g').selectAll('path').data(gs).join('path').attr('d',path).attr('fill',fill).attr('fill-rule','evenodd').attr('stroke',stroke).attr('stroke-width',width).attr('stroke-dasharray',dash)}
function line(ps,color,width=2,dash=null,arrow=false){svg.append('path').attr('d',d3.line()(ps)).attr('fill','none').attr('stroke',color).attr('stroke-width',width).attr('stroke-dasharray',dash).attr('marker-end',arrow?'url(#arrow)':null)}
function text(x,y,t,color='#242e31'){svg.append('text').attr('x',x).attr('y',y).attr('fill',color).attr('font-family','sans-serif').attr('font-size',15).text(t)}
const descriptions={original:'원형의 서로 다른 세 방향과 연결 중심 D, 진입 공간 E를 출발점으로 삼습니다. 원본을 단순화한 해석도입니다.',expanded:'마주 보는 경계를 벌려 큰 공동 중정을 만듭니다. 가장자리에 실내 연결 띠를 더해 면적과 이동 거리가 함께 늘어납니다.',overlap:'세 공간군의 실제 평면이 겹친 영역을 추출합니다. 붉은 면은 둘 이상의 중첩, 진한 면은 세 공간군의 공통 중첩입니다.',full:'중첩 전체를 삭제하면 남은 실내가 3개로 분리됩니다. 형태는 선명하지만 연속된 실내 연결 요구에는 맞지 않아 보류했습니다.',selected:'중첩부 가장자리는 실내 연결 띠로 남기고 안쪽을 비웁니다. E는 외부 모임, V는 채광·시선, G는 실내 순환을 담당합니다.'};
function render(){const state=document.querySelector('#state').value;svg.selectAll('*').remove();svg.append('rect').attr('x',-60).attr('y',-30).attr('width',1000).attr('height',900).attr('fill','white');const defs=svg.append('defs');defs.append('marker').attr('id','arrow').attr('viewBox','0 -5 10 10').attr('refX',9).attr('refY',0).attr('markerWidth',5).attr('markerHeight',5).attr('orient','auto').append('path').attr('d','M0,-5L10,0L0,5').attr('fill','#bc6b3f');
if(state==='original'){for(const k of 'ABCDE'){polys([{outer:S.original.regions[k]}],k==='D'?'#f0d7cf':k==='E'?'white':'#e2e4e3');const c=d3.polygonCentroid(S.original.regions[k]);text(...c,k)}polys([{outer:S.original.hearth}], '#424746')}
if(state==='expanded'){polys(A.floor,'#e2e4e3');polys(A.shared,'#f1d8cd','none');polys(A.void,'white','#44846c');}
if(state==='overlap'){Object.values(B.regions).forEach(g=>polys(g,'#e2e4e3'));polys(B.overlap,'#d79a90','#bd5253');polys(B.triple_overlap,'#9f514b','none');}
if(state==='full'){polys(B.full_subtraction,'#e2e4e3');polys(B.overlap,'none','#bd5253',1,'5 4');text(330,100,'3 SEPARATE PARTS','#bd5253');}
if(state==='selected'){polys(B.forecourt,'#eff2e6','#44846c',1);polys(B.floor,'#e2e4e3');if(document.querySelector('#programme').checked)B.rooms.forEach(r=>polys(r.geometry,r.color,'none'));else polys(B.shared,'#f1d8cd','none');polys(B.void,'white','#44846c',2);
if(document.querySelector('#details').checked){B.walls.filter(w=>w.kind!=='open').forEach(w=>line([w.a,w.b],w.kind==='glazing'?'#477ca0':'#242e31',w.kind==='glazing'?1.4:4));B.furniture.forEach(f=>polys(f.geometry,'white','#242e31',1.2))}
if(document.querySelector('#flows').checked){line(B.loop,'#bc6b3f',2.5,'7 5');Object.values(B.routes).forEach(ps=>line(ps,'#bc6b3f',2,null,true));line([[620,640],[565,515],B.external_ports.ENTRY],'#bc6b3f',2,null,true)}
for(const [k,p] of Object.entries({A:[287,249],B:[541,323],C:[335,474],S:[280,488],G:[369,234],V:[421,315],E:[580,571]}))text(...p,k);}
if(document.querySelector('#ghost').checked)for(const k of 'ABC')polys([{outer:S.original.regions[k]}],'none','#919e9a',1.2,'6 5');
line([[25,810],[25+S.U,810]],'#242e31',2);text(25,837,'0');text(25+S.U-20,837,'1 U');text(360,837,'RELATIVE UNITS / DESIGN PROPOSAL','#647174');
d3.select('#description').text(descriptions[state]);let m=state==='expanded'?A.metrics:state==='selected'?B.metrics:null;d3.select('#metrics').html(m?`실내 외곽 면적: ${m.enclosed_floor_U2.toFixed(3)} U²<br>중정: ${m.open_court_U2.toFixed(3)} U²<br>실내 연결: ${m.floor_components}개 연속 바닥<br>실내 공유 띠: ${m.shared_floor_U2.toFixed(3)} U²`:(state==='full'?'실내 3개로 분리 — 선정하지 않음':'면적 산정 전 과정도'));
svg.attr('data-state',state)}
d3.selectAll('select,input').on('change',render);d3.select('#download').on('click',()=>{const node=svg.node().cloneNode(true);node.setAttribute('xmlns','http://www.w3.org/2000/svg');const blob=new Blob([new XMLSerializer().serializeToString(node)],{type:'image/svg+xml'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='Fruchter_'+document.querySelector('#state').value+'.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});render();
</script></html>'''
(J/'output/Courtyard_Explorer.html').write_text(html.replace('__D3__',d3).replace('__DATA__',json.dumps(data,ensure_ascii=False)),encoding='utf-8')
print('Offline explorer written')
